          "formula": "$k = x_{1}\\cdot y_{1} \\implies xy = x_{1}y_{1}$",
          "example": "如由 $x=2.5,\\ y=4$ 算得定值 $k=2.5\\times 4=10$，确立关系式 $xy=10$。"
