      "chapter": "3.2.1 求代数式的值",
      "description": "在不单独求出每个字母具体值的情况下，先由已知等式提炼核心字母组合整体的数值，再通过对目标代数式提取公因数、添括号或重组，构造出已知整体结构，直接整体替换求值。",
