          "step": 1,
          "title": "整理已知条件，提炼“核心整体”的值",
          "description": "直接锁定已知等式，或将已知等式中的常数项移到等号右边，明确核心代数式整体（如 $x-2y=3$、$a^{2}-3a=1$）等于什么常数。",
          "formula": "由已知移项提炼 $M(\\text{字母组合}) = k$",
          "example": "如已知 $x-2y=3$，核心整体即为 $x-2y=3$；又如由 $a^{2}-3a-1=0$ 移项得核心整体 $a^{2}-3a=1$。"
