      "chapter": "27.1 反比例函数的概念",
      "description": "将函数解析式化为反比例函数三种标准形式 $y=\\frac{k}{x}$、$xy=k$ 或 $y=kx^{-1}$，核对自变量 $x$ 的次数为 $-1$ 且比例系数 $k\\neq 0$，完成概念辨析与含参求解。",
      "purpose": "准确判定给定函数关系式是否为反比例函数，或利用定义双重条件求参数值。",
      "applicability": [
        "判断给定的分式、负指数幂或乘积等式是否为 $y$ 关于 $x$ 的反比例函数，并指出比例系数 $k$。",
        "在一组函数关系式中逐一排查正比例函数、一次函数、分母含加减项或高次项的式子，统计反比例函数的个数。",
        "已知形如 $y=(m-a)x^{m^{2}-b}$ 或 $y=(m+a)x^{|2m|-b}$ 的函数是反比例函数，求参数 $m$ 的值。"
      ],
      "conditions": [
        "解析式可恒等变形为 $y=\\frac{k}{x}$、$xy=k$ 或 $y=kx^{-1}$ 三种标准形式之一",
        "自变量 $x$ 的次数严格等于 $-1$，且比例系数 $k\\neq 0$"
      ],
      "steps": [
        {
          "step": 1,
          "title": "将解析式整理并对照三种标准形式",
          "description": "观察或恒等变形给定关系式，对照分式形式 $y=\\frac{k}{x}$、乘积形式 $xy=k$ 或负整数指数幂形式 $y=kx^{-1}$：分母必须仅为自变量 $x$ 的一次单项式（或含常数系数如 $y=\\frac{3}{2x}=\\frac{3/2}{x}$），式子最外层不能含有常数加减项（如 $y=\\frac{8}{x}+7$ 不是 $y$ 关于 $x$ 的反比例函数）。",
          "formula": "$y=\\frac{k}{x} \\iff xy=k \\iff y=kx^{-1}\\ (k\\text{ 为常数，}k\\neq 0)$",
          "example": "如 $y=-\\frac{5}{3x}=\\frac{-5/3}{x}$、$y=2x^{-1}$、$xy=-1$ 均符合标准形式，比例系数分别为 $-\\frac{5}{3},\\ 2,\\ -1$。"
        },
        {
          "step": 2,
          "title": "核对自变量 $x$ 的次数等于 $-1$（或列指数方程）",
          "description": "检查自变量 $x$ 的指数：在分式形式 $\\frac{k}{x^{n}}$ 中分母 $x$ 的次数须为 $1$（如 $\\frac{3}{x^{2}}$ 指数为 $-2$，不符合）；在负指数形式 $y=Ax^{n}$ 中，直接令自变量 $x$ 的指数 $n=-1$ 列出关于参数的方程并求解。",
          "formula": "在 $y=Ax^{n}$ 中，令指数 $n=-1$",
          "example": "如 $y=(m-2)x^{3-m^{2}}$ 是反比例函数，令 $3-m^{2}=-1$，得 $m^{2}=4$，解得 $m=\\pm 2$。"
        },
        {
          "step": 3,
          "title": "检验比例系数 $k\\neq 0$，舍去增根并定解",
          "description": "验证比例系数是否为非零常数（仅写 $y=\\frac{k}{x}$ 而未说明 $k\\neq 0$ 时不一定为反比例函数）；对于含参问题，将步骤 2 求出的参数值代入比例系数 $A$ 中检验，舍去使 $A=0$ 的值，确定最终参数解。",
          "formula": "$\\begin{cases} \\text{指数 } n = -1 \\\\ \\text{系数 } A \\neq 0 \\end{cases}$",
          "example": "接上例：由比例系数 $m-2\\neq 0$ 得 $m\\neq 2$，故舍去 $m=2$，定解为 $m=-2$。"
        }
      ],
      "procedure": [
        {
          "step": 1,
          "action": "对照三种标准形式",
          "detail": "将关系式对照 y=k/x、xy=k 或 y=kx⁻¹，排除含加减常数项或分母非单项式的式子。"
        },
        {
          "step": 2,
          "action": "核对自变量 x 的指数为 -1",
          "detail": "确认分母 x 的次数为 1，或令负指数形式中 x 的指数等于 -1 列方程求解。"
        },
        {
          "step": 3,
          "action": "检验比例系数 k≠0 并定解",
          "detail": "代入检验比例系数不为 0，排除使系数为 0 的增根。"
        }
      ],
