        "已知反比例函数图象位于第一、三象限或第二、四象限，逆向列不等式求含参比例系数（如 $k-1$、$4-k$、$3m+4$）中参数的取值范围或筛选符合条件的参数值。",
        "已知反比例函数在每个象限（或 $x \\gt 0$ / $x \\lt 0$）内的增减性，或已知同一象限内两点横纵坐标的增减方向（如当 $x_{1} \\gt x_{2} \\gt 0$ 时 $y_{1} \\lt y_{2}$），逆向列不等式求参数范围。"
