          "step": 1,
          "title": "将解析式对准标准形式，提取比例系数（或已知性质条件）",
          "description": "将函数解析式化为 $y=\\frac{k}{x}$ 的形式，连同负号或含参式整体提取分子上的比例系数（如 $y=-\\frac{8}{x}$ 提取 $k=-8$，$y=\\frac{4-k}{x}$ 提取 $4-k$）；若分子含偶次方（如 $k^{2}+1$），利用偶次方非负性 $k^{2}\\ge 0$ 直接判定 $k^{2}+1 \\gt 0$；若已知单支图象，则直接读取该支所在的象限。",
          "formula": "$y=\\frac{A}{x} \\implies \\text{比例系数为 }A$（含偶次方时：$k^{2}\\ge 0 \\implies k^{2}+1 \\gt 0$）",
          "example": "如在 $y=-\\frac{8}{x}$ 中，比例系数 $k=-8 \\lt 0$；在 $y=\\frac{k^{2}+1}{x}$ 中，因 $k^{2}\\ge 0$，故比例系数 $k^{2}+1 \\gt 0$。"
