      "description": "通过移项将一元二次方程右边化为 $0$，再运用提公因式法（含提取整体括号因式）、公式法或十字相乘法将左边分解为两个一次因式的乘积 $A\\cdot B=0$，进而降次转化为 $A=0$ 或 $B=0$ 求解。",
      "purpose": "利用“两因式乘积为0则至少有一因式为0”的原理，将一元二次方程快速降次为两个一元一次方程求解。",
