          "formula": "$ax^{2}+bx+c=0\\ (a\\neq 0,\\ \\Delta \\ge 0) \\implies x_{1}+x_{2}=-\\frac{b}{a},\\quad x_{1}x_{2}=\\frac{c}{a}$",
