          "example": "如 $(x_{1}-x_{2})^{2}=(x_{1}+x_{2})^{2}-4x_{1}x_{2}$；又如 $\\frac{x_{2}}{x_{1}}+\\frac{x_{1}}{x_{2}}=\\frac{x_{1}^{2}+x_{2}^{2}}{x_{1}x_{2}}=\\frac{(x_{1}+x_{2})^{2}-2x_{1}x_{2}}{x_{1}x_{2}}$。"
