        "判断多项式是否为完全平方式，或已知 $ax^{2}+bx+c$ 是完全平方式求未知系数（注意中间项符号可正可负）。",
        "已知 $a\\pm b$ 与 $ab$（或 $a^{2}+b^{2}$、倒数和差 $x\\pm\\frac{1}{x}$），利用完全平方公式恒等变形求 $a^{2}+b^{2}$、$ab$ 或 $x^{2}+\\frac{1}{x^{2}}$ 的值。"
