          "formula": "$(a+b)(a-b) = (a)^{2} - (b)^{2} = a^{2} - b^{2}$",
          "example": "如 $(-a+2)(-a-2)=(-a)^{2}-2^{2}=a^{2}-4$；又如 $(5x+6y)(5x-6y)=(5x)^{2}-(6y)^{2}=25x^{2}-36y^{2}$。"
