      "description": "遵循“先算分式乘方、除法转为乘倒数、多项式先因式分解、再约去分子分母公因式”的标准流程，完成分式的乘法、除法、乘除混合运算及乘方混合化简求值，并按原式分母与除式不为 $0$ 检验代入值。",
      "purpose": "掌握分式乘除与乘方的核心化简程序，承接分式基本性质约分（P31）与因式分解（P24、P25），为分式加减混合运算（P36）与分式方程求解奠定运算基础。",
