      "pitfalls": [
        "把分式加减化简与解分式方程混淆，通分后直接把最简公分母丢掉（化简必须全程保留分母）。",
        "同分母分式相减时，忘记给减式多项式分子整体加括号，导致负号只作用在第一项上（如 $\\frac{3x}{2x-1}-\\frac{x+1}{2x-1}$ 错算成 $\\frac{3x-x+1}{2x-1}$）。",
        "在“先化简再自选数值求值”或由二次方程解出两根代入时，只检查化简后的分母，忘记排除使原分母或除式分子为 $0$ 的增根。"
      ],
      "exampleQuestionId": "ch18_3_3_q13",
      "exampleStepMapping": [
        {
          "step": 1,
          "title": "对应步骤 1（分解括号内两分母并确定最简公分母）",
          "detail": "将 $x^{2}-x=x(x-1)$ 与 $x^{2}-2x+1=(x-1)^{2}$ 因式分解，确定括号内最简公分母为 $x(x-1)^{2}$。"
        },
        {
          "step": 2,
          "title": "对应步骤 2（括号内通分并合并分子同类项）",
          "detail": "通分得 $\\frac{(x+3)(x-1)-x^{2}}{x(x-1)^{2}} = \\frac{x^{2}+2x-3-x^{2}}{x(x-1)^{2}} = \\frac{2x-3}{x(x-1)^{2}}$。"
        },
        {
          "step": 3,
          "title": "对应步骤 3（除法转乘倒数并约分）",
          "detail": "乘以倒数 $\\frac{x}{2x-3}$，约去 $x$ 与 $(2x-3)$ 得最简结果 $\\frac{1}{(x-1)^{2}} = \\frac{1}{x^{2}-2x+1}$。"
        },
        {
          "step": 4,
          "title": "对应步骤 4（检验有意义并整体代入求值）",
          "detail": "由 $x^{2}-2x-3=0$ 得 $x^{2}-2x=3$（根为 $x=3$ 或 $x=-1$，均使原式有意义），整体代入得 $\\frac{1}{3+1} = \\frac{1}{4}$。"
        }
      ],
