          "formula": "等腰 $+$ 一个 $60^{\\circ}$ 角 $\\implies$ 等边三角形；两个 $60^{\\circ}$ 角 $\\implies$ 等边三角形",
          "example": "如顶角 $120^{\\circ}$ 的等腰三角形中两底角为 $30^{\\circ}$，中垂线导出中间三角形两底角均为 $60^{\\circ}$，故为等边三角形。"
