          "description": "正数的绝对值是它本身，$0$ 的绝对值是 $0$，负数的绝对值是它的相反数（数轴上点到原点的距离）。",
          "formula": "$|a|=\\begin{cases} a & (a\\gt 0) \\\\ 0 & (a=0) \\\\ -a & (a\\lt 0) \\end{cases}$",
