          "formula": "$x_i \\to y_i = \\frac{k}{x_i}$（正负对称取值）",
          "example": "对 $y=-\\frac{6}{x}$，列出 $(-3,2),(-2,3),(-1,6),(1,-6),(2,-3),(3,-2)$ 等对称点。"
