          "formula": "$0 \\lt x \\lt \\min\\left(\\frac{a}{m}, \\frac{b}{n}\\right)$",
          "example": "解得 $x_{1}=1, x_{2}=9$，由 $8-2x \\gt 0$ 得 $x \\lt 4$，舍去 $x=9$，故小径宽为 $1\\text{m}$。"
