      "id": "P97",
      "name": "由数轴上点到原点的距离与点的平移求点表示的数",
      "grade": "七年级",
      "subject": "数学",
      "chapterGroup": "第一章 有理数",
      "chapter": "1.2.7 数轴上点到原点的距离与点的移动",
      "description": "在数轴上依据基准点（原点 $0$ 或已知起点 $a$）与给定距离或移动单位数 $d$，当未限定方向时严格分“向右（加）”和“向左（减）”两种情况讨论，完整求出所有符合条件的点所表示的数。",
      "purpose": "建立数轴上距离与平移的分类讨论意识，杜绝“未指明方向时漏掉另一侧解”的高频失误，直接衔接绝对值反求原数（P54）。",
      "applicability": [
        "求数轴上已知点到原点的距离，或比较多个点到原点的距离大小。",
        "已知数轴上一点到原点的距离为正数 $d$，反求该点表示的数（$\\pm d$）。",
        "已知数轴上表示数 $a$ 的点沿数轴移动 $d$ 个单位（未指明方向），分向左、向右两类求终点表示的数。"
      ],
      "conditions": [
        "题干涉及数轴上点到原点的距离计算、由距离反求原数，或点的沿轴平移求终点",
        "不含多边形在数轴上连续翻转的周期规律探究题"
      ],
      "steps": [
        {
          "step": 1,
          "title": "明确起点位置与距离/移动单位数 $d$",
          "description": "先找出基准起点：求“到原点的距离为 $d$”时起点为原点 $0$；求“表示数 $a$ 的点移动 $d$ 个单位”时起点为 $a$，并确认距离或步长 $d \\gt 0$。",
          "formula": "起点 $a$（到原点时 $a = 0$），步长 $d \\gt 0$",
          "example": "如表示数 $-2$ 的点 $A$ 沿数轴移动 $6$ 个单位，起点 $a = -2$，步长 $d = 6$。"
        },
        {
          "step": 2,
          "title": "核对方向条件：未指明方向必分“向右”“向左”两类",
          "description": "审题检查是否限定了“向右”或“向左”；若题干只说“距离原点 $d$ 个单位”或“沿数轴移动 $d$ 个单位”，必须在数轴左右两侧分类讨论，严禁只算单侧。",
          "formula": "未限定方向 $\\implies$ 情况① 向右移（$+$）；情况② 向左移（$-$）",
          "example": "“沿数轴移动 $6$ 个单位”未说方向，必须分向右移 $6$ 格和向左移 $6$ 格两种情况。"
        },
        {
          "step": 3,
          "title": "分别算出两解并合并作答",
          "description": "到原点距离为 $d$ 的点表示 $+d$ 或 $-d$（即 $\\pm d$）；从 $a$ 右移 $d$ 个单位得 $a + d$，左移 $d$ 个单位得 $a - d$，将两个结果用“或”完整写出。",
          "formula": "到原点距离为 $d \\implies \\pm d$；从 $a$ 移动 $d \\implies a + d$ 或 $a - d$",
          "example": "从 $-2$ 向右移 $6$ 个单位得 $-2 + 6 = 4$，向左移 $6$ 个单位得 $-2 - 6 = -8$，故为 $4$ 或 $-8$。"
        }
      ],
