      "chapterGroup": "第二章 有理数的运算",
      "chapter": "2.2.2 倒数",
      "description": "依据“乘积是 $1$ 的两个数互为倒数”（$0$ 没有倒数，倒数等于本身的数是 $\\pm 1$），先化简多重符号/绝对值并将带分数化为假分数、小数化为最简分数，再保持原数正负号不变、将分子与分母颠倒位置求得倒数。",
      "purpose": "熟练掌握整数、负数、带分数与小数的倒数求法，彻底区分“倒数（符号不变、分子分母颠倒）”与“相反数（只变符号）”，为有理数除法（P105）打下基础。",
