          "formula": "带分数 $\\to$ 假分数；小数 $\\to$ 最简分数；整数 $k = \\frac{k}{1}$",
          "example": "如 $-3\\frac{1}{5} = -\\frac{16}{5}$；$0.75 = \\frac{3}{4}$；$|-3| = 3 = \\frac{3}{1}$。"
