          "formula": "$\\frac{a}{b}\\ (a, b \\neq 0)$ 的倒数是 $\\frac{b}{a}$；$-\\frac{a}{b}$ 的倒数是 $-\\frac{b}{a}$",
          "example": "$-\\frac{16}{5}$ 的倒数是 $-\\frac{5}{16}$；$\\frac{3}{4}$ 的倒数是 $\\frac{4}{3}$；$-9$ 的倒数是 $-\\frac{1}{9}$。"
